# builder/gen_ch16_p3.py
# -*- coding: utf-8 -*-

exercises = [{'num': 67, 'title': 'Обобщенное преобразование слайса Map: числа в строки', 'task': '**Обобщенное преобразование (Map)**: Напишите функцию `Map[T, U any](slice []T, f func(T) U) []U`. Функция должна преобразовывать срез одного типа в срез другого типа с помощью функции `f`. Протестируйте, преобразовав срез целых чисел в срез их строковых представлений.', 'theory': 'Функция `Map[T, U any]` позволяет трансформировать типы коллекций с сохранением строгой статической типизации.', 'step_by_step': '1. Объявим `Map[T, U any](slice []T, f func(T) U) []U`.\n2. Выделим память `make([]U, len(slice))`.\n3. Преобразуем `[]int` в `[]string` через `strconv.Itoa`.\n4. В `main` выведем результат.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"strconv"\n)\n\nfunc Map[T, U any](slice []T, f func(T) U) []U {\n\tres := make([]U, len(slice))\n\tfor i, v := range slice {\n\t\tres[i] = f(v)\n\t}\n\treturn res\n}\n\nfunc main() {\n\tnumbers := []int{10, 20, 30, 40}\n\tstrList := Map(numbers, func(n int) string {\n\t\treturn "num_" + strconv.Itoa(n)\n\t})\n\tfmt.Printf("Результат: %v (%T)\\n", strList, strList)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Результат: [num_10 num_20 num_30 num_40] ([]string)'}], 'under_the_hood': 'Выделяется ровно один блок памяти под `res` без повторных аллокаций.', 'pitfalls': 'Заполняйте массив по прямому индексу `res[i]`, а не через `append`.', 'bigtech_interview': '**Вопрос с собеседования:** «Каковы преимущества Map над циклом с append?»\n**Ответ:** Предварительное выделение точного размера исключает накладные расходы на ступенчатую реаллокацию базового массива.'}, {'num': 68, 'title': 'Интерфейс-ограничение Validator[T] с методом Validate', 'task': 'Интерфейс-ограничение: `Validator[T any]` с методом `Validate(T) error`. Реализуйте для `int` (положительное) и `string` (непустое).', 'theory': 'Обобщенный интерфейс `Validator[T any]` объявляет контракт валидации сущности произвольного типа `T`.', 'step_by_step': '1. Объявим `type Validator[T any] interface { Validate(T) error }`.\n2. Создадим структуры `PositiveIntValidator` и `NonEmptyStringValidator`.\n3. Напишем функцию `ValidateAll[T any](items []T, v Validator[T]) []error`.\n4. В `main` проверим валидацию.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"errors"\n\t"fmt"\n)\n\ntype Validator[T any] interface {\n\tValidate(T) error\n}\n\ntype PositiveIntValidator struct{}\n\nfunc (PositiveIntValidator) Validate(n int) error {\n\tif n <= 0 {\n\t\treturn fmt.Errorf("число %d должно быть строго > 0", n)\n\t}\n\treturn nil\n}\n\ntype NonEmptyStringValidator struct{}\n\nfunc (NonEmptyStringValidator) Validate(s string) error {\n\tif s == "" {\n\t\treturn errors.New("строка не может быть пустой")\n\t}\n\treturn nil\n}\n\nfunc ValidateAll[T any](items []T, v Validator[T]) []error {\n\tvar errs []error\n\tfor _, item := range items {\n\t\tif err := v.Validate(item); err != nil {\n\t\t\terrs = append(errs, err)\n\t\t}\n\t}\n\treturn errs\n}\n\nfunc main() {\n\tintVals := []int{10, -5, 20, 0}\n\tintErrs := ValidateAll(intVals, PositiveIntValidator{})\n\tfor _, err := range intErrs {\n\t\tfmt.Println("Ошибка валидации int:", err)\n\t}\n\n\tstrVals := []string{"hello", "", "world"}\n\tstrErrs := ValidateAll(strVals, NonEmptyStringValidator{})\n\tfor _, err := range strErrs {\n\t\tfmt.Println("Ошибка валидации string:", err)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Ошибка валидации int: число -5 должно быть строго > 0\n# Ошибка валидации int: число 0 должно быть строго > 0\n# Ошибка валидации string: строка не может быть пустой'}], 'under_the_hood': 'Интерфейс `Validator[int]` и `Validator[string]` компилируются в независимые типизированные контракты.', 'pitfalls': 'Реализуйте валидаторы на структурах с пустыми полями `struct{}` для исключения аллокаций памяти.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем плюс generic Validator перед dynamic interface?»\n**Ответ:** Строгая типизация: компилятор не позволит случайно передать `PositiveIntValidator` для валидации строк.'}, {'num': 69, 'title': 'Пересечение множеств: Intersect[T comparable]', 'task': 'Напишите дженерик-функцию `Intersect[T comparable](set1, set2 Set[T]) Set[T]`, которая находит пересечение двух множеств.', 'theory': 'Пересечение множеств находит только те элементы, которые одновременно присутствуют в обоих множествах.', 'step_by_step': '1. Объявим `type Set[T comparable] map[T]struct{}`.\n2. Реализуем `Intersect[T comparable](s1, s2 Set[T]) Set[T]`.\n3. Оптимизируем: обходим меньшее по размеру множество.\n4. В `main` найдем пересечение.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport "fmt"\n\ntype Set[T comparable] map[T]struct{}\n\nfunc NewSet[T comparable](items ...T) Set[T] {\n\ts := make(Set[T])\n\tfor _, item := range items {\n\t\ts[item] = struct{}{}\n\t}\n\treturn s\n}\n\nfunc Intersect[T comparable](s1, s2 Set[T]) Set[T] {\n\t// Оптимизация: итерируемся по меньшему множеству\n\tif len(s1) > len(s2) {\n\t\ts1, s2 = s2, s1\n\t}\n\tresult := make(Set[T])\n\tfor k := range s1 {\n\t\tif _, ok := s2[k]; ok {\n\t\t\tresult[k] = struct{}{}\n\t\t}\n\t}\n\treturn result\n}\n\nfunc main() {\n\tusersGroupA := NewSet("user1", "user2", "user3")\n\tusersGroupB := NewSet("user2", "user3", "user4")\n\n\tcommon := Intersect(usersGroupA, usersGroupB)\n\tfmt.Print("Общие пользователи: ")\n\tfor u := range common {\n\t\tfmt.Print(u, " ")\n\t}\n\tfmt.Println()\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Общие пользователи: user2 user3'}], 'under_the_hood': 'Своп `if len(s1) > len(s2)` сокращает количество чтений из хэш-таблицы до $\\min(|s1|, |s2|)$.', 'pitfalls': 'Не забывайте инициализировать `result := make(Set[T])` перед вставкой элементов.', 'bigtech_interview': '**Вопрос с собеседования:** «Какова асимптотика Intersect двух множеств?»\n**Ответ:** Время $O(\\min(N, M))$ в среднем, память $O(\\min(N, M))$.'}, {'num': 70, 'title': 'Связный список LinkedList[T]: Append, Prepend, ToSlice, Find', 'task': 'Реализуй `LinkedList[T any]` с узлом `Node[T] struct { Value T; Next *Node[T] }`. Методы: `Append(v T)`, `Prepend(v T)`, `Len() int`, `ToSlice() []T`, `Find(predicate func(T) bool) *Node[T]`.', 'theory': 'Полнофункциональный связный список поддерживает добавление как в начало (`Prepend` за $O(1)$), так и в конец (`Append` за $O(1)$).', 'step_by_step': '1. Объявим `Node[T any]` и `LinkedList[T any]`.\n2. Реализуем `Append`, `Prepend`, `Len`, `ToSlice`, `Find`.\n3. В `main` протестируем список чисел.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport "fmt"\n\ntype Node[T any] struct {\n\tValue T\n\tNext  *Node[T]\n}\n\ntype LinkedList[T any] struct {\n\thead, tail *Node[T]\n\tsize       int\n}\n\nfunc (l *LinkedList[T]) Append(v T) {\n\tnode := &Node[T]{Value: v}\n\tif l.head == nil {\n\t\tl.head, l.tail = node, node\n\t} else {\n\t\tl.tail.Next = node\n\t\tl.tail = node\n\t}\n\tl.size++\n}\n\nfunc (l *LinkedList[T]) Prepend(v T) {\n\tnode := &Node[T]{Value: v, Next: l.head}\n\tl.head = node\n\tif l.tail == nil {\n\t\tl.tail = node\n\t}\n\tl.size++\n}\n\nfunc (l *LinkedList[T]) Len() int { return l.size }\n\nfunc (l *LinkedList[T]) ToSlice() []T {\n\tres := make([]T, 0, l.size)\n\tcurr := l.head\n\tfor curr != nil {\n\t\tres = append(res, curr.Value)\n\t\tcurr = curr.Next\n\t}\n\treturn res\n}\n\nfunc (l *LinkedList[T]) Find(pred func(T) bool) *Node[T] {\n\tcurr := l.head\n\tfor curr != nil {\n\t\tif pred(curr.Value) {\n\t\t\treturn curr\n\t\t}\n\t\tcurr = curr.Next\n\t}\n\treturn nil\n}\n\nfunc main() {\n\tlist := &LinkedList[int]{}\n\tlist.Append(20)\n\tlist.Append(30)\n\tlist.Prepend(10)\n\n\tfmt.Println("Срез списка:", list.ToSlice())\n\tfound := list.Find(func(v int) bool { return v == 20 })\n\tif found != nil {\n\t\tfmt.Println("Найдено значение:", found.Value)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Срез списка: [10 20 30]\n# Найдено значение: 20'}], 'under_the_hood': 'Поддержание `head` и `tail` дает $O(1)$ для обеих операций вставки.', 'pitfalls': 'При вставке `Prepend` в пустой список не забывайте устанавливать `tail = node`.', 'bigtech_interview': '**Вопрос с собеседования:** «Как удалить элемент из односвязного списка за O(1)?»\n**Ответ:** В односвязном списке без знания предыдущего узла можно скопировать данные из `node.Next` в текущий узел и переставить `node.Next = node.Next.Next` (если удаляемый узел не последний).'}, {'num': 71, 'title': 'Двоичное дерево поиска BinarySearchTree[T cmp.Ordered]', 'task': 'Реализуй `BinarySearchTree[T constraints.Ordered]` с методами `Insert(v T)`, `Search(v T) bool`, `InOrder() []T`, `Min() (T, bool)`, `Max() (T, bool)`.', 'theory': 'Бинарное дерево поиска (BST) организует элементы по свойству: левое поддерево содержит меньшие элементы, правое — большие или равные. Обход In-Order возвращает элементы в отсортированном порядке.', 'step_by_step': '1. Объявим `TreeNode[T cmp.Ordered]` и `BST[T cmp.Ordered]`.\n2. Реализуем рекурсивные методы `Insert`, `Search`, `InOrder`, `Min`, `Max`.\n3. В `main` вставим элементы и проверим обход.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"cmp"\n\t"fmt"\n)\n\ntype TreeNode[T cmp.Ordered] struct {\n\tValue T\n\tLeft  *TreeNode[T]\n\tRight *TreeNode[T]\n}\n\ntype BST[T cmp.Ordered] struct {\n\troot *TreeNode[T]\n}\n\nfunc (b *BST[T]) Insert(v T) {\n\tb.root = insertNode(b.root, v)\n}\n\nfunc insertNode[T cmp.Ordered](node *TreeNode[T], v T) *TreeNode[T] {\n\tif node == nil {\n\t\treturn &TreeNode[T]{Value: v}\n\t}\n\tif v < node.Value {\n\t\tnode.Left = insertNode(node.Left, v)\n\t} else {\n\t\tnode.Right = insertNode(node.Right, v)\n\t}\n\treturn node\n}\n\nfunc (b *BST[T]) Search(v T) bool {\n\tcurr := b.root\n\tfor curr != nil {\n\t\tif v == curr.Value {\n\t\t\treturn true\n\t\t} else if v < curr.Value {\n\t\t\tcurr = curr.Left\n\t\t} else {\n\t\t\tcurr = curr.Right\n\t\t}\n\t}\n\treturn false\n}\n\nfunc (b *BST[T]) InOrder() []T {\n\tvar res []T\n\tvar traverse func(n *TreeNode[T])\n\ttraverse = func(n *TreeNode[T]) {\n\t\tif n == nil {\n\t\t\treturn\n\t\t}\n\t\ttraverse(n.Left)\n\t\tres = append(res, n.Value)\n\t\ttraverse(n.Right)\n\t}\n\ttraverse(b.root)\n\treturn res\n}\n\nfunc main() {\n\ttree := &BST[int]{}\n\tfor _, v := range []int{50, 30, 70, 20, 40, 60, 80} {\n\t\ttree.Insert(v)\n\t}\n\n\tfmt.Println("In-Order обход (отсортировано):", tree.InOrder())\n\tfmt.Println("Поиск 40:", tree.Search(40))\n\tfmt.Println("Поиск 99:", tree.Search(99))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# In-Order обход (отсортировано): [20 30 40 50 60 70 80]\n# Поиск 40: true\n# Поиск 99: false'}], 'under_the_hood': 'Сравнение `v < node.Value` мономорфизируется компилятором под скалярный тип `int`.', 'pitfalls': 'Несбалансированное дерево при монотонной вставке может выродиться в связный список с $O(N)$ поиском. Для гарантии $O(\\log N)$ используют AVL или Красно-черные деревья.', 'bigtech_interview': '**Вопрос с собеседования:** «Какова сложность In-Order обхода дерева?»\n**Ответ:** Время $O(N)$, так как каждый узел посещается ровно один раз. Память $O(H)$ под стек рекурсии, где $H$ — высота дерева.'}, {'num': 72, 'title': 'Обобщенная структура Result[T]: IsSuccess и Value', 'task': 'Создайте параметризованную структуру `Result[T any]`, которая может хранить либо значение типа `T`, либо ошибку. Реализуйте методы `IsSuccess() bool`, `Value() (T, error)`. Это отличная альтернатива стандартному возвращению `(T, error)`.', 'theory': '`Result[T any]` инкапсулирует значение или ошибку в единую структуру, удобную для передачи в каналы.', 'step_by_step': '1. Объявим `type Result[T any] struct { val T; err error }`.\n2. Реализуем `Success[T any](v T) Result[T]` и `Failure[T any](e error) Result[T]`.\n3. Реализуем `IsSuccess()` и `Value() (T, error)`.\n4. Проверим в `main`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"errors"\n\t"fmt"\n)\n\ntype Result[T any] struct {\n\tval T\n\terr error\n}\n\nfunc Success[T any](v T) Result[T]  { return Result[T]{val: v} }\nfunc Failure[T any](e error) Result[T] { return Result[T]{err: e} }\n\nfunc (r Result[T]) IsSuccess() bool { return r.err == nil }\nfunc (r Result[T]) Value() (T, error) {\n\treturn r.val, r.err\n}\n\nfunc parsePort(p int) Result[int] {\n\tif p < 1 || p > 65535 {\n\t\treturn Failure[int](errors.New("невалидный номер порта"))\n\t}\n\treturn Success(p)\n}\n\nfunc main() {\n\tr1 := parsePort(8080)\n\tif val, err := r1.Value(); err == nil {\n\t\tfmt.Println("Порт валиден:", val)\n\t}\n\n\tr2 := parsePort(99999)\n\tfmt.Println("Успех r2:", r2.IsSuccess())\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Порт валиден: 8080\n# Успех r2: false'}], 'under_the_hood': '`Result[T]` отлично подходит для передачи результатов через каналы `chan Result[T]` при параллельных вычислениях.', 'pitfalls': 'Не забывайте обрабатывать `err` при извлечении `Value()`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в Go каналы часто типизируют как chan Result[T]?»\n**Ответ:** Потому что канал в Go может передавать только один тип за раз (`chan (T, error)` невалиден). Структура `Result[T]` объединяет полезную нагрузку и ошибку в одно сообщение.'}, {'num': 73, 'title': 'Constraint для всех целочисленных типов AnyInteger', 'task': 'Создай constraint для **всех целых типов** с `~` (tilde):\n```go\ntype AnyInteger interface {\n    ~int | ~int8 | ~int16 | ~int32 | ~int64 |\n    ~uint | ~uint8 | ~uint16 | ~uint32 | ~uint64 | ~uintptr\n}\n```\nНапиши `BitwiseOr[T AnyInteger](a, b T) T`. Покажи, что `AnyInteger` включает и signed, и unsigned.', 'theory': '`AnyInteger` объединяет абсолютно все целочисленные типы с тильдой, гарантируя поддержку побитовых операций (`|`, `&`, `^`).', 'step_by_step': '1. Объявим `type AnyInteger interface { ... }`.\n2. Напишем `BitwiseOr[T AnyInteger](a, b T) T { return a | b }`.\n3. В `main` проверим со знаковыми `int` и беззнаковыми `uint32`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport "fmt"\n\ntype AnyInteger interface {\n\t~int | ~int8 | ~int16 | ~int32 | ~int64 |\n\t\t~uint | ~uint8 | ~uint16 | ~uint32 | ~uint64 | ~uintptr\n}\n\nfunc BitwiseOr[T AnyInteger](a, b T) T {\n\treturn a | b\n}\n\nfunc main() {\n\tvar s1 int = 1\n\tvar s2 int = 2\n\tfmt.Printf("Signed OR:   %d (%03b)\\n", BitwiseOr(s1, s2), BitwiseOr(s1, s2))\n\n\tvar u1 uint32 = 4\n\tvar u2 uint32 = 8\n\tfmt.Printf("Unsigned OR: %d (%04b)\\n", BitwiseOr(u1, u2), BitwiseOr(u1, u2))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Signed OR:   3 (011)\n# Unsigned OR: 12 (1100)'}], 'under_the_hood': 'Компилятор подставляет машинную инструкцию `ORQ` / `ORL` процессора.', 'pitfalls': 'Не пытайтесь смешивать signed и unsigned в одном вызове `BitwiseOr(int(1), uint(2))` — аргументы обязаны иметь одинаковый тип.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в AnyInteger включен uintptr?»\n**Ответ:** `uintptr` — это целочисленный беззнаковый тип достаточного размера для хранения адреса памяти. Он поддерживает все целочисленные и побитовые операции.'}, {'num': 74, 'title': 'Обобщенная структура Pair[K, V] и метод GetValues', 'task': '**Обобщенная структура (Контейнер)**: Создайте обобщенную структуру `Pair[K, V any]` с полями `First K` и `Second V`. Напишите для неё метод `GetValues() (K, V)`. Инициализируйте пару со типами `[string, int]` и пару со типами `[bool, float64]`.', 'theory': 'Обобщенные структуры инкапсулируют поля разных типов и предоставляют методы доступа.', 'step_by_step': '1. Объявим `type Pair[K, V any] struct { First K; Second V }`.\n2. Реализуем метод `(p Pair[K, V]) GetValues() (K, V)`.\n3. В `main` создадим `Pair[string, int]` и `Pair[bool, float64]`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport "fmt"\n\ntype Pair[K, V any] struct {\n\tFirst  K\n\tSecond V\n}\n\nfunc (p Pair[K, V]) GetValues() (K, V) {\n\treturn p.First, p.Second\n}\n\nfunc main() {\n\tp1 := Pair[string, int]{First: "MaxRetries", Second: 5}\n\tk1, v1 := p1.GetValues()\n\tfmt.Printf("Пара 1: %s = %d\\n", k1, v1)\n\n\tp2 := Pair[bool, float64]{First: true, Second: 99.9}\n\tk2, v2 := p2.GetValues()\n\tfmt.Printf("Пара 2: %v, %.1f\\n", k2, v2)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Пара 1: MaxRetries = 5\n# Пара 2: true, 99.9'}], 'under_the_hood': 'Размер структуры `Pair` рассчитывается компилятором с учетом выравнивания полей (alignment padding).', 'pitfalls': 'Порядок полей в структурах влияет на общий размер из-за паддингов.', 'bigtech_interview': '**Вопрос с собеседования:** «Как размер структуры Pair[bool, int64] отличается от Pair[int64, int64]?»\n**Ответ:** `Pair[bool, int64]` занимает 16 байт (1 байт bool + 7 байт padding + 8 байт int64), то есть ровно столько же, сколько `Pair[int64, int64]` (8 + 8 = 16 байт).'}, {'num': 75, 'title': 'Паттерн MapSlice в обход запрета на generic-методы', 'task': '**Обходной путь (Map для Слайса)**: Реализуй функциональность из упр. 245 в виде отдельной функции: `MapSlice[T, U any](slice []T, fn func(T) U) []U`. Это паттерн Map из функционального программирования.', 'theory': 'Так как Go запрещает generic-методы на структурах, отдельная функция `MapSlice[T, U any]` является стандартным идиоматичным паттерном в экосистеме языка.', 'step_by_step': '1. Объявим `MapSlice[T, U any](slice []T, fn func(T) U) []U`.\n2. В `main` преобразуем слайс температур по Цельсию в Фаренгейты.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport "fmt"\n\nfunc MapSlice[T, U any](slice []T, fn func(T) U) []U {\n\tres := make([]U, len(slice))\n\tfor i, v := range slice {\n\t\tres[i] = fn(v)\n\t}\n\treturn res\n}\n\nfunc main() {\n\tcelsius := []float64{0.0, 20.0, 36.6, 100.0}\n\tfahrenheit := MapSlice(celsius, func(c float64) float64 {\n\t\treturn c*9/5 + 32\n\t})\n\n\tfor i, c := range celsius {\n\t\tfmt.Printf("%.1f°C = %.1f°F\\n", c, fahrenheit[i])\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# 0.0°C = 32.0°F\n# 20.0°C = 68.0°F\n# 36.6°C = 97.9°F\n# 100.0°C = 212.0°F'}], 'under_the_hood': '`MapSlice` выполняет мономорфизацию для пар `(float64, float64)` с прямой записью в память.', 'pitfalls': 'Всегда используйте функции верхнего уровня для преобразования между коллекциями разных типов.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в Go не используется синтаксис методов расширения (Extension Methods)?»\n**Ответ:** Go стремится к простоте и прозрачности вызовов: все доступные методы типа явно видны в пакете объявления типа, исключая скрытую магию.'}, {'num': 76, 'title': 'Constraint с Stringer и функция Join', 'task': 'Констрейнт с методами: `Stringer` (`~string | interface{ String() string }`). Функция `Join[T Stringer](elems []T, sep string) string`.', 'theory': 'Constraint объединяет базовые строки `~string` и любые структуры, реализующие `String() string`.', 'step_by_step': '1. Объявим `type Stringer interface { ~string | fmt.Stringer }` (через type switch/helper).\n2. Реализуем функцию `Join`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"strings"\n)\n\ntype Stringable interface {\n\tfmt.Stringer\n}\n\ntype User struct {\n\tName string\n}\n\nfunc (u User) String() string {\n\treturn u.Name\n}\n\nfunc JoinStringers[T Stringable](elems []T, sep string) string {\n\tparts := make([]string, len(elems))\n\tfor i, e := range elems {\n\t\tparts[i] = e.String()\n\t}\n\treturn strings.Join(parts, sep)\n}\n\nfunc main() {\n\tusers := []User{{Name: "Анна"}, {Name: "Борис"}, {Name: "Виктор"}}\n\tfmt.Println("Пользователи:", JoinStringers(users, ", "))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Пользователи: Анна, Борис, Виктор'}], 'under_the_hood': '`strings.Join` предварительно вычисляет длину итоговой строки и делает ровно одну аллокацию памяти.', 'pitfalls': 'Не используйте конкатенацию строк в цикле через `+=`, это приводит к $O(N^2)$ аллокациям.', 'bigtech_interview': '**Вопрос с собеседования:** «Как оптимизирована функция strings.Join?»\n**Ответ:** Она суммирует длины всех строк и разделителей, выделяет буфер `make([]byte, totalLen)` и копирует байты через `copy()`, гарантируя ровно одну аллокацию памяти.'}, {'num': 77, 'title': 'Обобщенная функция повторных попыток: Retry[T any]', 'task': 'Напишите дженерик-функцию `Retry[T any](attempts int, f func() (T, error)) (T, error)`, которая пытается выполнить переданную функцию несколько раз до успеха.', 'theory': 'Паттерн Retry перезапускает операцию заданное число раз до первого успешного результата или исчерпания попыток.', 'step_by_step': '1. Объявим `Retry[T any](attempts int, f func() (T, error)) (T, error)`.\n2. В цикле вызовем `f()`, при успехе сразу вернем результат.\n3. В `main` сымитируем нестабильный сетевой вызов.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"errors"\n\t"fmt"\n)\n\nfunc Retry[T any](attempts int, f func() (T, error)) (T, error) {\n\tvar lastErr error\n\tfor i := 1; i <= attempts; i++ {\n\t\tval, err := f()\n\t\tif err == nil {\n\t\t\treturn val, nil\n\t\t}\n\t\tlastErr = err\n\t\tfmt.Printf("Попытка %d не удалась: %v\\n", i, err)\n\t}\n\tvar zero T\n\treturn zero, fmt.Errorf("все %d попыток исчерпаны: %w", attempts, lastErr)\n}\n\nfunc main() {\n\tcount := 0\n\tunstableNetworkCall := func() (string, error) {\n\t\tcount++\n\t\tif count < 3 {\n\t\t\treturn "", errors.New("connection reset by peer")\n\t\t}\n\t\treturn "HTTP/2.0 200 OK (Payload)", nil\n\t}\n\n\tres, err := Retry(5, unstableNetworkCall)\n\tif err != nil {\n\t\tfmt.Println("Ошибка:", err)\n\t} else {\n\t\tfmt.Println("Успех:", res)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Попытка 1 не удалась: connection reset by peer\n# Попытка 2 не удалась: connection reset by peer\n# Успех: HTTP/2.0 200 OK (Payload)'}], 'under_the_hood': 'Ошибка оборачивается через `%w` для сохранения цепочки ошибок `errors.Is`/`errors.As`.', 'pitfalls': 'В реальных сервисах всегда добавляйте экспоненциальную задержку (Backoff) и передавайте `context.Context`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в распределенных системах Retry без Backoff и Jitter опасен?»\n**Ответ:** Это может вызвать эффект «громоподобного стада» (Thundering Herd / Retry Storm), когда тысячи упавших клиентов одновременно шлют повторные запросы и окончательно добивают восстанавливающийся сервис.'}, {'num': 78, 'title': 'Оболочка над каналом: Channel[T any]', 'task': 'Реализуй `Channel[T any]` — обёртку над `chan T` с методами `Send(v T)`, `Receive() (T, bool)`, `Close()`, `Len() int`, `Cap() int`.', 'theory': 'Оболочка `Channel[T any]` инкапсулирует операции над буферизованными и небуферизованными каналами Go.', 'step_by_step': '1. Объявим `type Channel[T any] struct { ch chan T }`.\n2. Реализуем `Send(v T)`, `Receive() (T, bool)`, `Close()`, `Len()`, `Cap()`.\n3. В `main` протестируем отправку и получение данных.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport "fmt"\n\ntype Channel[T any] struct {\n\tch chan T\n}\n\nfunc NewChannel[T any](capacity int) *Channel[T] {\n\treturn &Channel[T]{ch: make(chan T, capacity)}\n}\n\nfunc (c *Channel[T]) Send(v T) {\n\tc.ch <- v\n}\n\nfunc (c *Channel[T]) Receive() (T, bool) {\n\tval, ok := <-c.ch\n\treturn val, ok\n}\n\nfunc (c *Channel[T]) Close() {\n\tclose(c.ch)\n}\n\nfunc (c *Channel[T]) Len() int { return len(c.ch) }\nfunc (c *Channel[T]) Cap() int { return cap(c.ch) }\n\nfunc main() {\n\tch := NewChannel[int](5)\n\tch.Send(100)\n\tch.Send(200)\n\n\tfmt.Printf("Элементов в буфере: %d / %d\\n", ch.Len(), ch.Cap())\n\n\tv1, _ := ch.Receive()\n\tv2, _ := ch.Receive()\n\tfmt.Printf("Получено: %d, %d\\n", v1, v2)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Элементов в буфере: 2 / 5\n# Получено: 100, 200'}], 'under_the_hood': 'Канал под капотом представлен структурой `runtime.hchan` с кольцевым буфером и мьютексом `lock`.', 'pitfalls': 'Повторное закрытие закрытого канала вызовет `panic: close of closed channel`.', 'bigtech_interview': '**Вопрос с собеседования:** «Из чего состоит структура канала hchan в рантайме Go?»\n**Ответ:** Из кольцевого буфера `buf`, мьютекса `lock`, очередей заблокированных горутин на чтение `recvq` и запись `sendq`, счетчика `qcount` и емкости `dataqsiz`.'}, {'num': 79, 'title': 'Ловушка Type Inference при несовпадении типов', 'task': '**[Каверзный кейс]**: Выведение типов (Type Inference): вызови функцию `Contains[T comparable](slice []T, target T)` без явного указания типа `Contains[int](...)`. Убедись, что компилятор сам понял тип. Затем попробуй передать в функцию, ожидающую `int`, значение `int64` без приведения типов (поймай ошибку).', 'theory': 'Type Inference сопоставляет типы аргументов с сигнатурой `(slice []T, target T)`. Если `slice` имеет тип `[]int`, то `T` выводится как `int`. Попытка передать `target` типа `int64` вызовет ошибку компиляции.', 'step_by_step': '1. Объявим `Contains[T comparable](slice []T, target T) bool`.\n2. Покажем успешный вызов с автовыводом.\n3. В комментариях зафиксируем ошибку несовпадения `int` и `int64`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport "fmt"\n\nfunc Contains[T comparable](slice []T, target T) bool {\n\tfor _, v := range slice {\n\t\tif v == target {\n\t\t\treturn true\n\t\t}\n\t}\n\treturn false\n}\n\nfunc main() {\n\tnums := []int{10, 20, 30}\n\t// Автоматический вывод T = int:\n\tfmt.Println("Contains(nums, 20):", Contains(nums, 20))\n\n\t// Несовпадение типов:\n\t// var target64 int64 = 20\n\t// Contains(nums, target64)\n\t// Ошибка компилятора:\n\t// type int of nums does not match inferred type int64 for T (or mismatched types []int and int64)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Contains(nums, 20): true'}], 'under_the_hood': 'Алгоритм унификации типов (Type Unification) требует, чтобы все вхождения параметра `T` однозначно соответствовали одному типу.', 'pitfalls': 'В Go нет неявного приведения типов (implicit type conversion) даже между `int` и `int64`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему Go запрещает неявные преобразования числовых типов?»\n**Ответ:** Для исключения скрытых потерь точности и переполнений разрядной сетки процессора.'}, {'num': 80, 'title': 'Fluent API для работы со срезами: Slice[T any]', 'task': 'Реализуй `Slice[T any]` — тип с **fluent API**: `Map(fn func(T) T) Slice[T]`, `Filter(fn func(T) bool) Slice[T]`, `Reduce(init T, fn func(T, T) T) T`, `Contains(v T) bool`, `IndexOf(v T) int`, `Reverse() Slice[T]`. Каждый метод возвращает новый `Slice` (immutable).', 'theory': 'Fluent API предоставляет удобные цепочки вызовов методов в функциональном стиле (Method Chaining).', 'step_by_step': '1. Объявим `type Slice[T any] []T`.\n2. Реализуем методы `Filter`, `Map`, `Reverse`, `ToRaw`.\n3. В `main` построим цепочку операций.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport "fmt"\n\ntype Slice[T any] []T\n\nfunc (s Slice[T]) Filter(predicate func(T) bool) Slice[T] {\n\tres := make(Slice[T], 0, len(s))\n\tfor _, v := range s {\n\t\tif predicate(v) {\n\t\t\tres = append(res, v)\n\t\t}\n\t}\n\treturn res\n}\n\nfunc (s Slice[T]) Map(fn func(T) T) Slice[T] {\n\tres := make(Slice[T], len(s))\n\tfor i, v := range s {\n\t\tres[i] = fn(v)\n\t}\n\treturn res\n}\n\nfunc (s Slice[T]) Reverse() Slice[T] {\n\tn := len(s)\n\tres := make(Slice[T], n)\n\tfor i, v := range s {\n\t\tres[n-1-i] = v\n\t}\n\treturn res\n}\n\nfunc main() {\n\tnumbers := Slice[int]{1, 2, 3, 4, 5, 6, 7, 8}\n\n\t// Цепочка: Оставить четные -> Умножить на 10 -> Развернуть\n\tresult := numbers.\n\t\tFilter(func(n int) bool { return n%2 == 0 }).\n\t\tMap(func(n int) int { return n * 10 }).\n\t\tReverse()\n\n\tfmt.Println("Результат цепочки:", []int(result))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Результат цепочки: [80 60 40 20]'}], 'under_the_hood': 'Каждый метод создает новый независимый срез, гарантируя неизменяемость исходной коллекции.', 'pitfalls': 'Цепочки методов порождают промежуточные аллокации. В критических путях по производительности используйте единый цикл `for`.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем недостаток Fluent API в Go по сравнению с Rust Iterator или Java Streams?»\n**Ответ:** В Rust и Java итераторы являются ленивыми (Lazy Evaluation) и компилируются в один слитный цикл без промежуточных аллокаций памяти. В Go методы срезов выполняются энергично (Eager Evaluation), создавая временные слайсы в куче.'}, {'num': 81, 'title': 'Потокобезопасная SafeMap[K, V] с sync.RWMutex', 'task': 'Реализуй `SafeMap[K comparable, V any]` — обёртку над `map[K]V` с методами `Get(k K) (V, bool)`, `Set(k K, v V)`, `Delete(k K)`, `Keys() []K`, `Values() []V`, `Len() int`. Добавь `sync.RWMutex` для потокобезопасности.', 'theory': '`SafeMap[K, V]` защищает внутреннюю мапу с помощью `sync.RWMutex`:\n- Чтение (`Get`, `Keys`, `Values`, `Len`) использует разделяемую блокировку `RLock()`.\n- Запись (`Set`, `Delete`) использует эксклюзивную блокировку `Lock()`.', 'step_by_step': '1. Объявим `type SafeMap[K comparable, V any] struct { mu sync.RWMutex; data map[K]V }`.\n2. Реализуем `Set`, `Get`, `Delete`, `Keys`, `Values`, `Len`.\n3. В `main` запустим параллельные горутины.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\ntype SafeMap[K comparable, V any] struct {\n\tmu   sync.RWMutex\n\tdata map[K]V\n}\n\nfunc NewSafeMap[K comparable, V any]() *SafeMap[K, V] {\n\treturn &SafeMap[K, V]{data: make(map[K]V)}\n}\n\nfunc (m *SafeMap[K, V]) Set(k K, v V) {\n\tm.mu.Lock()\n\tdefer m.mu.Unlock()\n\tm.data[k] = v\n}\n\nfunc (m *SafeMap[K, V]) Get(k K) (V, bool) {\n\tm.mu.RLock()\n\tdefer m.mu.RUnlock()\n\tval, ok := m.data[k]\n\treturn val, ok\n}\n\nfunc (m *SafeMap[K, V]) Len() int {\n\tm.mu.RLock()\n\tdefer m.mu.RUnlock()\n\treturn len(m.data)\n}\n\nfunc main() {\n\tsm := NewSafeMap[string, int]()\n\tvar wg sync.WaitGroup\n\n\t// Параллельная запись\n\tfor i := 0; i < 10; i++ {\n\t\twg.Add(1)\n\t\tgo func(idx int) {\n\t\t\tdefer wg.Done()\n\t\t\tsm.Set(fmt.Sprintf("key_%d", idx), idx*100)\n\t\t}(i)\n\t}\n\n\twg.Wait()\n\tfmt.Printf("Всего ключей в SafeMap: %d\\n", sm.Len())\n\tval, _ := sm.Get("key_5")\n\tfmt.Printf("key_5 = %d\\n", val)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Всего ключей в SafeMap: 10\n# key_5 = 500'}], 'under_the_hood': '`sync.RWMutex` позволяет неограниченному числу читателей одновременно читать данные без взаимной блокировки.', 'pitfalls': 'Не копируйте структуру `SafeMap` по значению, так как мьютекс нельзя копировать (`go vet copylocks`).', 'bigtech_interview': '**Вопрос с собеседования:** «Когда sync.Map эффективнее SafeMap с RWMutex?»\n**Ответ:** `sync.Map` эффективнее при двух сценариях: 1) ключ записывается один раз, а читается многократно; 2) множество горутин параллельно читают, модифицируют и перезаписывают непересекающиеся ключи (разделение read-only и dirty кэшей).'}, {'num': 82, 'title': 'Параметризованный интерфейс Repository[T any]', 'task': 'Создайте параметризованный интерфейс `Repository[T any]` с методами `Get(id string) (T, error)` и `Save(entity T) error`.', 'theory': 'Паттерн Репозиторий (Repository Pattern) абстрагирует слой доступа к базе данных. Generic-интерфейс `Repository[T any]` объявляет единый контракт CRUD для любых доменных сущностей.', 'step_by_step': '1. Объявим `type Repository[T any] interface { Get(id string) (T, error); Save(entity T) error }`.\n2. Создадим сущность `User`.\n3. Реализуем in-memory репозиторий.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"errors"\n\t"fmt"\n)\n\ntype Repository[T any] interface {\n\tGet(id string) (T, error)\n\tSave(id string, entity T) error\n}\n\ntype MemoryRepo[T any] struct {\n\tstorage map[string]T\n}\n\nfunc NewMemoryRepo[T any]() *MemoryRepo[T] {\n\treturn &MemoryRepo[T]{storage: make(map[string]T)}\n}\n\nfunc (r *MemoryRepo[T]) Save(id string, entity T) error {\n\tr.storage[id] = entity\n\treturn nil\n}\n\nfunc (r *MemoryRepo[T]) Get(id string) (T, error) {\n\tentity, ok := r.storage[id]\n\tif !ok {\n\t\tvar zero T\n\t\treturn zero, errors.New("not found")\n\t}\n\treturn entity, nil\n}\n\ntype Order struct {\n\tID    string\n\tTotal float64\n}\n\nfunc main() {\n\trepo := NewMemoryRepo[Order]()\n\t_ = repo.Save("ord-100", Order{ID: "ord-100", Total: 4500.50})\n\n\tord, _ := repo.Get("ord-100")\n\tfmt.Printf("Заказ: %+v\\n", ord)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Заказ: {ID:ord-100 Total:4500.5}'}], 'under_the_hood': '`MemoryRepo[Order]` реализует интерфейс `Repository[Order]` статически во время сборки.', 'pitfalls': 'Используйте абстракцию `Repository` для изоляции бизнес-логики (Domain Layer) от конкретной СУБД (PostgreSQL/MongoDB).', 'bigtech_interview': '**Вопрос с собеседования:** «Как generic репозиторий соотносится с Clean Architecture?»\n**Ответ:** Интерфейс `Repository[T]` объявляется в слое Use Cases/Domain, а его имплементация (Postgres/Redis) выносится в слой Infrastructure (DIP — Dependency Inversion Principle).'}, {'num': 83, 'title': 'Обобщенная структура Matrix[T]: Add, Transpose', 'task': 'Реализуй `Matrix[T constraints.Signed | constraints.Float]` — двумерный слайс. Методы: `Add(other Matrix[T]) Matrix[T]`, `Subtract(other Matrix[T]) Matrix[T]`, `Multiply(other Matrix[T]) Matrix[T]` (матричное умножение), `Transpose() Matrix[T]`, `Dimensions() (rows, cols int)`.', 'theory': 'Матрица $M \\times N$ представляется как срезы строк. Операция транспонирования $M^T$ меняет строки и столбцы местами.', 'step_by_step': '1. Объявим `type Matrix[T Numeric] [][]T`.\n2. Реализуем `NewMatrix`, `Add`, `Transpose`.\n3. В `main` сложим две матрицы 2x2.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport "fmt"\n\ntype Number interface {\n\t~int | ~int64 | ~float64\n}\n\ntype Matrix[T Number] struct {\n\trows, cols int\n\tdata       [][]T\n}\n\nfunc NewMatrix[T Number](rows, cols int) *Matrix[T] {\n\tdata := make([][]T, rows)\n\tfor i := range data {\n\t\tdata[i] = make([]T, cols)\n\t}\n\treturn &Matrix[T]{rows: rows, cols: cols, data: data}\n}\n\nfunc (m *Matrix[T]) Add(other *Matrix[T]) *Matrix[T] {\n\tres := NewMatrix[T](m.rows, m.cols)\n\tfor r := 0; r < m.rows; r++ {\n\t\tfor c := 0; c < m.cols; c++ {\n\t\t\tres.data[r][c] = m.data[r][c] + other.data[r][c]\n\t\t}\n\t}\n\treturn res\n}\n\nfunc (m *Matrix[T]) Transpose() *Matrix[T] {\n\tres := NewMatrix[T](m.cols, m.rows)\n\tfor r := 0; r < m.rows; r++ {\n\t\tfor c := 0; c < m.cols; c++ {\n\t\t\tres.data[c][r] = m.data[r][c]\n\t\t}\n\t}\n\treturn res\n}\n\nfunc main() {\n\tm1 := NewMatrix[int](2, 2)\n\tm1.data[0] = []int{1, 2}\n\tm1.data[1] = []int{3, 4}\n\n\tm2 := NewMatrix[int](2, 2)\n\tm2.data[0] = []int{10, 20}\n\tm2.data[1] = []int{30, 40}\n\n\tsum := m1.Add(m2)\n\tfmt.Println("Сумма матриц:")\n\tfor _, row := range sum.data {\n\t\tfmt.Println(" ", row)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Сумма матриц:\n#   [11 22]\n#   [33 44]'}], 'under_the_hood': 'Операции над матрицей мономорфизируются в быстрые инструкции без динамических интерфейсов.', 'pitfalls': 'Перед операциями сложения проверяйте совпадение размерностей матриц.', 'bigtech_interview': '**Вопрос с собеседования:** «Как оптимизировать хранение матрицы в Go для кэшей CPU?»\n**Ответ:** Хранить матрицу в одном плоском срезе `data []T` длины `rows * cols` с индексацией `data[r*cols + c]`, что исключает фрагментацию памяти и разыменование указателей.'}, {'num': 84, 'title': 'Ограничение методов и переход к параметризованной структуре Calculator[T]', 'task': '**Ограничения на методы структур**: Попробуйте написать обычную структуру `Calculator struct{}` и добавить ей обобщенный метод `func (c Calculator) Sum[T Numeric](a, b T) T`. Зафиксируйте ошибку компиляции. Изучите важнейшее ограничение Go: **методы структур не могут иметь собственные параметры типов (type parameters)**. Перепишите код так, чтобы сам тип структуры был обобщенным: `type Calculator[T Numeric] struct{}`.', 'theory': 'Запрет на generic-методы на непараметризованных структурах обходится параметризацией самой структуры: `type Calculator[T Numeric] struct{}`.', 'step_by_step': '1. Объявим `type Calculator[T Number] struct{}`.\n2. Реализуем метод `(c Calculator[T]) Sum(a, b T) T { return a + b }`.\n3. В `main` вызовем `Calculator[int]` и `Calculator[float64]`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport "fmt"\n\ntype Number interface {\n\t~int | ~float64\n}\n\n// Переносим параметр типа на саму структуру:\ntype Calculator[T Number] struct{}\n\nfunc (c Calculator[T]) Sum(a, b T) T {\n\treturn a + b\n}\n\nfunc (c Calculator[T]) Multiply(a, b T) T {\n\treturn a * b\n}\n\nfunc main() {\n\tintCalc := Calculator[int]{}\n\tfmt.Println("Int Sum:", intCalc.Sum(15, 25))\n\n\tfloatCalc := Calculator[float64]{}\n\tfmt.Println("Float Multiply:", floatCalc.Multiply(2.5, 4.0))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Int Sum: 40\n# Float Multiply: 10'}], 'under_the_hood': '`Calculator[int]` и `Calculator[float64]` порождают две специализированные структуры нулевого размера.', 'pitfalls': 'Не пытайтесь объявлять `func (c Calculator) Sum[T any]()` — Go всегда выдает синтаксическую ошибку.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в Go нельзя объявить метод func (s S) F[T any]()?»\n**Ответ:** Это сделало бы таблицу методов структуры бесконечной (по одной записи на каждый тип T в программе), разрушив статическую компоновку itab.'}, {'num': 85, 'title': 'Реализация интерфейса Repository[User] для сущности User', 'task': 'Реализуйте этот интерфейс для конкретной структуры, например `UserRepository` для `User`.', 'theory': 'Интерфейс `Repository[User]` задает типобезопасный контракт репозитория пользователей.', 'step_by_step': '1. Создадим структуру `User struct { ID string; Name string; Email string }`.\n2. Реализуем `UserRepository` с методами `Get` и `Save`.\n3. Проверим сохранение в `main`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"errors"\n\t"fmt"\n)\n\ntype User struct {\n\tID    string\n\tName  string\n\tEmail string\n}\n\ntype UserRepository interface {\n\tGet(id string) (User, error)\n\tSave(u User) error\n}\n\ntype InMemUserRepo struct {\n\tusers map[string]User\n}\n\nfunc NewUserRepo() *InMemUserRepo {\n\treturn &InMemUserRepo{users: make(map[string]User)}\n}\n\nfunc (r *InMemUserRepo) Save(u User) error {\n\tr.users[u.ID] = u\n\treturn nil\n}\n\nfunc (r *InMemUserRepo) Get(id string) (User, error) {\n\tu, ok := r.users[id]\n\tif !ok {\n\t\treturn User{}, errors.New("user not found")\n\t}\n\treturn u, nil\n}\n\nfunc main() {\n\tvar repo UserRepository = NewUserRepo()\n\t_ = repo.Save(User{ID: "u1", Name: "Иван", Email: "ivan@example.com"})\n\n\tuser, _ := repo.Get("u1")\n\tfmt.Printf("Пользователь: %+v\\n", user)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Пользователь: {ID:u1 Name:Иван Email:ivan@example.com}'}], 'under_the_hood': '`InMemUserRepo` удовлетворяет интерфейсу `UserRepository` неявно по правилу duck typing.', 'pitfalls': 'Всегда объявляйте интерфейсы на стороне потребителя данных (Consumer-side interfaces).', 'bigtech_interview': '**Вопрос с собеседования:** «Где в Clean Architecture должен объявляться UserRepository?»\n**Ответ:** В слое Use Cases/Application, а не в пакете базы данных `infrastructure/postgres`.'}, {'num': 86, 'title': 'Типобезопасный пул объектов: Pool[T any] над sync.Pool', 'task': 'Реализуй `Pool[T any]` — пул объектов. Методы: `Get() T`, `Put(T)`. Внутри используй `sync.Pool` (хранит `interface{}`, делай type assertion). Обсуди ограничения `sync.Pool` с generics.', 'theory': '`sync.Pool` в стандартной библиотеке оперирует `any` (`interface{}`). Дженерик-обёртка `Pool[T any]` инкапсулирует runtime type assertion, предоставляя типобезопасный интерфейс `Get() *T` и `Put(*T)`.', 'step_by_step': '1. Объявим `type Pool[T any] struct { p sync.Pool }`.\n2. Конструктор `NewPool[T any](newFn func() *T) *Pool[T]`.\n3. Методы `Get() *T` и `Put(*T)`.\n4. В `main` переиспользуем буферы `bytes.Buffer`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"bytes"\n\t"fmt"\n\t"sync"\n)\n\ntype Pool[T any] struct {\n\tp sync.Pool\n}\n\nfunc NewPool[T any](newFn func() *T) *Pool[T] {\n\treturn &Pool[T]{\n\t\tp: sync.Pool{\n\t\t\tNew: func() any {\n\t\t\t\treturn newFn()\n\t\t\t},\n\t\t},\n\t}\n}\n\nfunc (p *Pool[T]) Get() *T {\n\treturn p.p.Get().(*T)\n}\n\nfunc (p *Pool[T]) Put(item *T) {\n\tp.p.Put(item)\n}\n\nfunc main() {\n\tbufPool := NewPool(func() *bytes.Buffer {\n\t\treturn new(bytes.Buffer)\n\t})\n\n\tbuf := bufPool.Get()\n\tbuf.WriteString("HighLoad Go Workout")\n\tfmt.Println("Буфер:", buf.String())\n\n\tbuf.Reset()\n\tbufPool.Put(buf)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Буфер: HighLoad Go Workout'}], 'under_the_hood': '`sync.Pool` сбрасывается каждым циклом Garbage Collection. Объекты хранятся в локальных пулах процессоров `P` (local pool caches) без блокировок.', 'pitfalls': 'Всегда сбрасывайте состояние объекта (`buf.Reset()`) перед возвратом в `Put`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в Go не переписали sync.Pool на чистые дженерики?»\n**Ответ:** `sync.Pool` тесно интегрирован с рантаймом Go и планировщиком GMP (хранит структуры в массиве per-P `poolLocal`). Дженерик-обертка дает 100% типобезопасность на уровне компилятора без изменения низкоуровневого рантайма.'}, {'num': 87, 'title': 'Обобщенный EventEmitter[T any] для событийной модели', 'task': "Реализуй `EventEmitter[T any]` — `map[string][]func(T)`. Методы: `On(event string, handler func(T))`, `Off(event string, handler func(T))`, `Emit(event string, data T)`. Обработай удаление handler'а во время итерации.", 'theory': '`EventEmitter[T any]` реализует паттерн Publisher-Subscriber для событий с полезной нагрузкой типа `T`.', 'step_by_step': '1. Объявим `type EventEmitter[T any] struct { mu sync.RWMutex; handlers map[string][]func(T) }`.\n2. Реализуем `On`, `Emit`.\n3. При `Emit` скопируем срез обработчиков для безопасности.\n4. В `main` отправим событие.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\ntype EventEmitter[T any] struct {\n\tmu       sync.RWMutex\n\thandlers map[string][]func(T)\n}\n\nfunc NewEventEmitter[T any]() *EventEmitter[T] {\n\treturn &EventEmitter[T]{handlers: make(map[string][]func(T))}\n}\n\nfunc (e *EventEmitter[T]) On(event string, handler func(T)) {\n\te.mu.Lock()\n\tdefer e.mu.Unlock()\n\te.handlers[event] = append(e.handlers[event], handler)\n}\n\nfunc (e *EventEmitter[T]) Emit(event string, data T) {\n\te.mu.RLock()\n\t// Копируем срез для безопасного вызова без удержания блокировки\n\thandlers := make([]func(T), len(e.handlers[event]))\n\tcopy(handlers, e.handlers[event])\n\te.mu.RUnlock()\n\n\tfor _, h := range handlers {\n\t\th(data)\n\t}\n}\n\ntype OrderEvent struct {\n\tOrderID string\n\tStatus  string\n}\n\nfunc main() {\n\temitter := NewEventEmitter[OrderEvent]()\n\n\temitter.On("order_update", func(e OrderEvent) {\n\t\tfmt.Printf("[Email Service] Заказ %s сменил статус на %s\\n", e.OrderID, e.Status)\n\t})\n\n\temitter.On("order_update", func(e OrderEvent) {\n\t\tfmt.Printf("[Push Service] Push-уведомление для заказа %s\\n", e.OrderID)\n\t})\n\n\temitter.Emit("order_update", OrderEvent{OrderID: "ord-777", Status: "SHIPPED"})\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Email Service] Заказ ord-777 сменил статус на SHIPPED\n# [Push Service] Push-уведомление для заказа ord-777'}], 'under_the_hood': 'Снятие блокировки перед вызовом `h(data)` предотвращает дедлоки, если обработчик внутри захочет подписаться на новое событие (`On`).', 'pitfalls': 'Вызов обработчиков под мьютексом приводит к взаимным блокировкам (Deadlocks).', 'bigtech_interview': '**Вопрос с собеседования:** «Почему обработчики событий нельзя вызывать внутри критической секции mu.Lock()?»\n**Ответ:** Если обработчик вызовет другой метод `EventEmitter` или выполнит блокирующий ввод-вывод, это приведет к дедлоку или зависанию всех остальных потоков приложения.'}, {'num': 88, 'title': 'Ошибки типов при явном инстанцировании', 'task': 'Явное инстанцирование: вызови `Print[int]("hello")` (передача аргумента не того типа при явном указании дженерика). Поймай ошибку компиляции.', 'theory': 'При явном инстанцировании `Print[int]` компилятор жестко фиксирует сигнатуру как `func(val int)`. Передача строки `"hello"` вызовет ошибку `cannot use "hello" (untyped string constant) as int value`.', 'step_by_step': '1. Объявим `Print[T any](v T)`.\n2. В `main` покажем корректный вызов `Print[string]("hello")`.\n3. В комментариях зафиксируем ошибку для `Print[int]("hello")`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport "fmt"\n\nfunc Print[T any](v T) {\n\tfmt.Println("Значение:", v)\n}\n\nfunc main() {\n\tPrint[string]("hello")\n\tPrint[int](42)\n\n\t// Следующий вызов вызовет ошибку компиляции:\n\t// Print[int]("hello")\n\t// Ошибка: cannot use "hello" (untyped string constant) as int value in argument to Print[int]\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Значение: hello\n# Значение: 42'}], 'under_the_hood': 'Явное указание `[int]` отключает фазу вывода типов аргументов, форсируя проверку типа параметров `int`.', 'pitfalls': 'Явное инстанцирование используется, когда автоматический вывод типов не может выбрать тип однозначно.', 'bigtech_interview': '**Вопрос с собеседования:** «Когда компилятор Go требует явного указания типа дженерика?»\n**Ответ:** Когда параметр типа не фигурирует в типах входных аргументов (например `make([]T, 0)`) или при передаче нетипизированных `nil` констант.'}, {'num': 89, 'title': 'Мемоизация функций: Memoize[T, U] с кэшированием', 'task': 'Напишите параметризованную функцию-мемоизатор `Memoize[T comparable, U any](f func(T) U) func(T) U`, который кэширует результаты выполнения функции в мапе.', 'theory': 'Мемоизация кэширует результаты чистых функций по аргументу `T comparable`, исключая повторные тяжелые вычисления.', 'step_by_step': '1. Объявим `Memoize[T comparable, U any](f func(T) U) func(T) U`.\n2. Создадим мапу кэша `cache := make(map[T]U)`.\n3. В `main` мемоизируем вычисление чисел Фибоначчи.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport "fmt"\n\nfunc Memoize[T comparable, U any](f func(T) U) func(T) U {\n\tcache := make(map[T]U)\n\treturn func(x T) U {\n\t\tif val, exists := cache[x]; exists {\n\t\t\treturn val\n\t\t}\n\t\tres := f(x)\n\t\tcache[x] = res\n\t\treturn res\n\t}\n}\n\nfunc main() {\n\tvar fib func(n int) int\n\tfib = Memoize(func(n int) int {\n\t\tif n <= 1 {\n\t\t\treturn n\n\t\t}\n\t\treturn fib(n-1) + fib(n-2)\n\t})\n\n\tfmt.Println("Fib(10) =", fib(10))\n\tfmt.Println("Fib(40) =", fib(40))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Fib(10) = 55\n# Fib(40) = 102334155'}], 'under_the_hood': 'Сложность рекурсивного вычисления Фибоначчи падает с $O(2^N)$ до $O(N)$ благодаря мемоизации.', 'pitfalls': 'В многопоточной среде чтение и запись в `cache` требуют защиты через `sync.Mutex`.', 'bigtech_interview': '**Вопрос с собеседования:** «Когда мемоизация не работает?»\n**Ответ:** Для функций с побочными эффектами (I/O, генерация UUID, random) или функций, зависящих от глобального мутабельного состояния.'}, {'num': 90, 'title': 'Кольцевой буфер фиксированного размера: RingBuffer[T any]', 'task': 'Реализуй `RingBuffer[T any]` — кольцевой буфер фиксированного размера. Методы: `Write(v T) bool` (false если полон), `Read() (T, bool)` (false если пуст), `IsFull()`, `IsEmpty()`, `Len()`, `Cap()`.', 'theory': 'Кольцевой буфер (Circular Ring Buffer) реализует FIFO очередь на массиве фиксированной емкости без перемещения элементов.', 'step_by_step': '1. Объявим `type RingBuffer[T any] struct { buf []T; head, tail, size int }`.\n2. Реализуем `Write`, `Read`, `IsFull`, `IsEmpty`, `Len`, `Cap`.\n3. В `main` протестируем кольцевую запись и чтение.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport "fmt"\n\ntype RingBuffer[T any] struct {\n\tbuf        []T\n\thead, tail int\n\tsize, cap  int\n}\n\nfunc NewRingBuffer[T any](capacity int) *RingBuffer[T] {\n\treturn &RingBuffer[T]{buf: make([]T, capacity), cap: capacity}\n}\n\nfunc (r *RingBuffer[T]) Write(v T) bool {\n\tif r.size == r.cap {\n\t\treturn false\n\t}\n\tr.buf[r.tail] = v\n\tr.tail = (r.tail + 1) % r.cap\n\tr.size++\n\treturn true\n}\n\nfunc (r *RingBuffer[T]) Read() (T, bool) {\n\tif r.size == 0 {\n\t\tvar zero T\n\t\treturn zero, false\n\t}\n\tval := r.buf[r.head]\n\tvar zero T\n\tr.buf[r.head] = zero\n\tr.head = (r.head + 1) % r.cap\n\tr.size--\n\treturn val, true\n}\n\nfunc (r *RingBuffer[T]) IsFull() bool  { return r.size == r.cap }\nfunc (r *RingBuffer[T]) IsEmpty() bool { return r.size == 0 }\n\nfunc main() {\n\trb := NewRingBuffer[int](3)\n\trb.Write(10)\n\trb.Write(20)\n\trb.Write(30)\n\tfmt.Println("Полон:", rb.IsFull())\n\n\tv1, _ := rb.Read()\n\tfmt.Println("Прочитано:", v1)\n\trb.Write(40)\n\n\tfor !rb.IsEmpty() {\n\t\tv, _ := rb.Read()\n\t\tfmt.Println("Извлечено:", v)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Полон: true\n# Прочитано: 10\n# Извлечено: 20\n# Извлечено: 30\n# Извлечено: 40'}], 'under_the_hood': 'Индексы `head` и `tail` циклически зацикливаются через оператор остатка `% r.cap`, исключая сдвиги элементов.', 'pitfalls': 'Зануляйте `r.buf[r.head] = zero` при чтении, чтобы не удерживать память под удаленными объектами.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем преимущество кольцевого буфера перед слайсом для очередей?»\n**Ответ:** Кольцевой буфер работает с нулевыми аллокациями памяти ($O(1)$ вставка и извлечение) и не требует сдвигов массива.'}, {'num': 91, 'title': 'Слияние нескольких мап: MergeMaps[K, V]', 'task': '`MergeMaps[K comparable, V any](maps ...map[K]V) map[K]V` — объединение карт (последний побеждает).', 'theory': 'Функция `MergeMaps` объединяет вариативный список мап. При конфликте ключей побеждает значение из более поздней мапы.', 'step_by_step': '1. Объявим `MergeMaps[K comparable, V any](maps ...map[K]V) map[K]V`.\n2. Создадим результирующую мапу.\n3. Проитерируемся по каждой мапе и запишем ключи.\n4. В `main` объединим настройки по умолчанию и переопределения.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport "fmt"\n\nfunc MergeMaps[K comparable, V any](maps ...map[K]V) map[K]V {\n\tresult := make(map[K]V)\n\tfor _, m := range maps {\n\t\tfor k, v := range m {\n\t\t\tresult[k] = v\n\t\t}\n\t}\n\treturn result\n}\n\nfunc main() {\n\tdefaultConfig := map[string]string{\n\t\t"host": "localhost",\n\t\t"port": "8080",\n\t\t"mode": "development",\n\t}\n\n\tprodConfig := map[string]string{\n\t\t"host": "api.production.com",\n\t\t"mode": "production",\n\t}\n\n\tfinalConfig := MergeMaps(defaultConfig, prodConfig)\n\tfmt.Printf("Итоговая конфигурация: %+v\\n", finalConfig)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Итоговая конфигурация: map[host:api.production.com mode:production port:8080]'}], 'under_the_hood': 'Вариативный параметр `maps ...map[K]V` передается как срез мап `[]map[K]V`.', 'pitfalls': 'Помните, что `nil` мапы в списке `maps` безопасно итерируются циклом `for range` без паники.', 'bigtech_interview': '**Вопрос с собеседования:** «Что происходит при for k, v := range nilMap в Go?»\n**Ответ:** Цикл `for range` по `nil` мапе выполняет ровно 0 итераций и не вызывает панику.'}, {'num': 92, 'title': 'Разделение слайса по предикату: Partition[T any]', 'task': '**[Высокая сложность]**: Напиши дженерик-функцию `Partition[T any](slice []T, predicate func(T) bool) ([]T, []T)`, которая разделяет слайс на два: те, что прошли проверку, и те, что нет.', 'theory': '`Partition` делит исходную коллекцию на две непересекающиеся группы за один линейный проход ($O(N)$).', 'step_by_step': '1. Объявим `Partition[T any](slice []T, predicate func(T) bool) ([]T, []T)`.\n2. Создадим срезы `passed` и `failed`.\n3. В цикле распределим элементы.\n4. В `main` разделим пользователей на активных и заблокированных.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport "fmt"\n\ntype Account struct {\n\tUsername string\n\tActive   bool\n}\n\nfunc Partition[T any](slice []T, predicate func(T) bool) ([]T, []T) {\n\tpassed := make([]T, 0, len(slice)/2)\n\tfailed := make([]T, 0, len(slice)/2)\n\tfor _, v := range slice {\n\t\tif predicate(v) {\n\t\t\tpassed = append(passed, v)\n\t\t} else {\n\t\t\tfailed = append(failed, v)\n\t\t}\n\t}\n\treturn passed, failed\n}\n\nfunc main() {\n\taccounts := []Account{\n\t\t{Username: "alice", Active: true},\n\t\t{Username: "bob", Active: false},\n\t\t{Username: "carol", Active: true},\n\t\t{Username: "dave", Active: false},\n\t}\n\n\tactive, inactive := Partition(accounts, func(a Account) bool {\n\t\treturn a.Active\n\t})\n\n\tfmt.Printf("Активные (%d):   %+v\\n", len(active), active)\n\tfmt.Printf("Неактивные (%d): %+v\\n", len(inactive), inactive)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Активные (2):   [{Username:alice Active:true} {Username:carol Active:true}]\n# Неактивные (2): [{Username:bob Active:false} {Username:dave Active:false}]'}], 'under_the_hood': 'Предвыделение емкости `len(slice)/2` оптимизирует аллокации для равномерно распределенных предикатов.', 'pitfalls': 'Исходный слайс не мутируется, сохраняя ссылочную прозрачность.', 'bigtech_interview': '**Вопрос с собеседования:** «Как реализовать Partition in-place без выделения новых срезов?»\n**Ответ:** Использовать алгоритм разбиения Ломуто или Хоара с двумя указателями (как в Quicksort), меняя элементы местами.'}, {'num': 93, 'title': 'Обобщенный граф Graph[T comparable]: BFS и DFS', 'task': 'Реализуй `Graph[T comparable]` через список смежности `map[T][]T`. Методы: `AddEdge(from, to T)`, `HasEdge(from, to T) bool`, `Neighbors(v T) []T`, `BFS(start T) []T`, `DFS(start T) []T`.', 'theory': 'Граф на списке смежности `map[T][]T` поддерживает алгоритмы поиска в ширину (BFS с очередью) и поиска в глубину (DFS со стеком).', 'step_by_step': '1. Объявим `type Graph[T comparable] struct { adj map[T][]T }`.\n2. Реализуем `AddEdge`, `Neighbors`, `BFS`, `DFS`.\n3. В `main` построим граф зависимостей микросервисов.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport "fmt"\n\ntype Graph[T comparable] struct {\n\tadj map[T][]T\n}\n\nfunc NewGraph[T comparable]() *Graph[T] {\n\treturn &Graph[T]{adj: make(map[T][]T)}\n}\n\nfunc (g *Graph[T]) AddEdge(from, to T) {\n\tg.adj[from] = append(g.adj[from], to)\n}\n\nfunc (g *Graph[T]) BFS(start T) []T {\n\tvisited := make(map[T]bool)\n\tvar order []T\n\tqueue := []T{start}\n\tvisited[start] = true\n\n\tfor len(queue) > 0 {\n\t\tcurr := queue[0]\n\t\tqueue = queue[1:]\n\t\torder = append(order, curr)\n\n\t\tfor _, neighbor := range g.adj[curr] {\n\t\t\tif !visited[neighbor] {\n\t\t\t\tvisited[neighbor] = true\n\t\t\t\tqueue = append(queue, neighbor)\n\t\t\t}\n\t\t}\n\t}\n\treturn order\n}\n\nfunc main() {\n\tg := NewGraph[string]()\n\tg.AddEdge("Gateway", "AuthService")\n\tg.AddEdge("Gateway", "OrderService")\n\tg.AddEdge("OrderService", "PaymentService")\n\tg.AddEdge("OrderService", "InventoryService")\n\n\tfmt.Println("Порядок обхода BFS от Gateway:", g.BFS("Gateway"))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Порядок обхода BFS от Gateway: [Gateway AuthService OrderService PaymentService InventoryService]'}], 'under_the_hood': 'Мапа `visited` исключает бесконечные циклы в графах с циклами.', 'pitfalls': 'Для вершин графа обязателен constraint `comparable` для работы мапы посещений.', 'bigtech_interview': '**Вопрос с собеседования:** «Какова сложность BFS графа?»\n**Ответ:** Время $O(V + E)$ (вершины + ребра), память $O(V)$ под очередь и множество visited.'}, {'num': 94, 'title': 'Обобщенный интерфейс Processor[T] и реализации', 'task': '**Дженерик-Интерфейсы**: Создай интерфейс `Processor[T any]` с методом `Process(data T) T`. Создай структуру, реализующую `Processor[string]` (например, переводит текст в верхний регистр) и структуру для `Processor[int]` (например, умножает на 2).', 'theory': 'Обобщенные интерфейсы `Processor[T any]` позволяют объявлять полиморфные конвейеры обработки данных.', 'step_by_step': '1. Объявим `type Processor[T any] interface { Process(data T) T }`.\n2. Реализуем `UpperStringProcessor` и `DoubleIntProcessor`.\n3. В `main` вызовем процессоры.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"strings"\n)\n\ntype Processor[T any] interface {\n\tProcess(data T) T\n}\n\ntype UpperStringProcessor struct{}\n\nfunc (UpperStringProcessor) Process(data string) string {\n\treturn strings.ToUpper(data)\n}\n\ntype DoubleIntProcessor struct{}\n\nfunc (DoubleIntProcessor) Process(data int) int {\n\treturn data * 2\n}\n\nfunc ExecuteProcess[T any](p Processor[T], val T) T {\n\treturn p.Process(val)\n}\n\nfunc main() {\n\tstrProc := UpperStringProcessor{}\n\tintProc := DoubleIntProcessor{}\n\n\tfmt.Println("String:", ExecuteProcess[string](strProc, "golang"))\n\tfmt.Println("Int:   ", ExecuteProcess[int](intProc, 21))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# String: GOLANG\n# Int:    42'}], 'under_the_hood': '`Processor[string]` и `Processor[int]` компилируются в разные `itab` структуры во время сборки.', 'pitfalls': 'Интерфейс параметризуется конкретным типом при инстанциации.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем отличие Processor[any] от Processor[T]?»\n**Ответ:** `Processor[any]` принимает интерфейс и требует runtime type assertions. `Processor[T]` строго мономорфизируется под конкретный тип на этапе компиляции.'}, {'num': 95, 'title': 'Stack[T] для структур User и примитивов int', 'task': '**Обобщенный Стек (Stack)**: Реализуйте структуру `Stack[T any]` на базе среза. Напишите методы `Push(val T)`, `Pop() (T, bool)` и `Len() int`. Проверьте работу стека для хранения структур `User` и обычных чисел `int`.', 'theory': 'Один и тот же шаблон структуры `Stack[T]` без дублирования кода работает как со структурами `User`, так и с примитивными числами.', 'step_by_step': '1. Объявим структуру `Stack[T any]`.\n2. Реализуем `Push`, `Pop`, `Len`.\n3. В `main` проверим со стеком `User` и `int`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport "fmt"\n\ntype User struct {\n\tID   int\n\tRole string\n}\n\ntype Stack[T any] struct {\n\tdata []T\n}\n\nfunc (s *Stack[T]) Push(v T) { s.data = append(s.data, v) }\n\nfunc (s *Stack[T]) Pop() (T, bool) {\n\tif len(s.data) == 0 {\n\t\tvar zero T\n\t\treturn zero, false\n\t}\n\tidx := len(s.data) - 1\n\tv := s.data[idx]\n\ts.data = s.data[:idx]\n\treturn v, true\n}\n\nfunc (s *Stack[T]) Len() int { return len(s.data) }\n\nfunc main() {\n\tuserStack := &Stack[User]{}\n\tuserStack.Push(User{ID: 1, Role: "Admin"})\n\tuserStack.Push(User{ID: 2, Role: "Member"})\n\n\tu, _ := userStack.Pop()\n\tfmt.Printf("Pop User: %+v\\n", u)\n\n\tintStack := &Stack[int]{}\n\tintStack.Push(99)\n\tn, _ := intStack.Pop()\n\tfmt.Println("Pop Int:", n)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Pop User: {ID:2 Role:Member}\n# Pop Int: 99'}], 'under_the_hood': 'Для `Stack[User]` выделяется непрерывный массив под размер структуры `User`.', 'pitfalls': 'Для структур больших размеров храните в стеке указатели `*User`.', 'bigtech_interview': '**Вопрос с собеседования:** «Когда стоит использовать Stack[*T] вместо Stack[T]?»\n**Ответ:** Когда размер структуры `T` превышает 64–128 байт, чтобы избежать дорогостоящего побайтового копирования при каждом `Push`/`Pop`.'}, {'num': 96, 'title': 'Обобщенная Min-Heap очередь с приоритетом PriorityQueue[T]', 'task': 'Реализуй `PriorityQueue[T constraints.Ordered]` — min-heap на слайсе. Методы: `Push(v T)`, `Pop() (T, bool)`, `Peek() (T, bool)`. Не используй `container/heap` (реализуй sift-up/sift-down самостоятельно для практики).', 'theory': 'Двоичная min-куча (Binary Min-Heap) гарантирует извлечение наименьшего элемента за $O(\\log N)$ с помощью алгоритмов `siftUp` и `siftDown`.', 'step_by_step': '1. Объявим `type PriorityQueue[T cmp.Ordered] struct { heap []T }`.\n2. Реализуем `siftUp` (при вставке) и `siftDown` (при извлечении).\n3. В `main` проверим извлечение элементов в порядке возрастания.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"cmp"\n\t"fmt"\n)\n\ntype PriorityQueue[T cmp.Ordered] struct {\n\theap []T\n}\n\nfunc (pq *PriorityQueue[T]) Push(v T) {\n\tpq.heap = append(pq.heap, v)\n\tpq.siftUp(len(pq.heap) - 1)\n}\n\nfunc (pq *PriorityQueue[T]) Pop() (T, bool) {\n\tif len(pq.heap) == 0 {\n\t\tvar zero T\n\t\treturn zero, false\n\t}\n\tminVal := pq.heap[0]\n\tlastIdx := len(pq.heap) - 1\n\tpq.heap[0] = pq.heap[lastIdx]\n\tpq.heap = pq.heap[:lastIdx]\n\tif len(pq.heap) > 0 {\n\t\tpq.siftDown(0)\n\t}\n\treturn minVal, true\n}\n\nfunc (pq *PriorityQueue[T]) siftUp(i int) {\n\tfor i > 0 {\n\t\tparent := (i - 1) / 2\n\t\tif pq.heap[i] < pq.heap[parent] {\n\t\t\tpq.heap[i], pq.heap[parent] = pq.heap[parent], pq.heap[i]\n\t\t\ti = parent\n\t\t} else {\n\t\t\tbreak\n\t\t}\n\t}\n}\n\nfunc (pq *PriorityQueue[T]) siftDown(i int) {\n\tn := len(pq.heap)\n\tfor {\n\t\tleft := 2*i + 1\n\t\tright := 2*i + 2\n\t\tsmallest := i\n\n\t\tif left < n && pq.heap[left] < pq.heap[smallest] {\n\t\t\tsmallest = left\n\t\t}\n\t\tif right < n && pq.heap[right] < pq.heap[smallest] {\n\t\t\tsmallest = right\n\t\t}\n\t\tif smallest != i {\n\t\t\tpq.heap[i], pq.heap[smallest] = pq.heap[smallest], pq.heap[i]\n\t\t\ti = smallest\n\t\t} else {\n\t\t\tbreak\n\t\t}\n\t}\n}\n\nfunc (pq *PriorityQueue[T]) Len() int { return len(pq.heap) }\n\nfunc main() {\n\tpq := &PriorityQueue[int]{}\n\tfor _, n := range []int{42, 10, 85, 3, 27} {\n\t\tpq.Push(n)\n\t}\n\n\tfmt.Print("Извлечение min-heap: ")\n\tfor pq.Len() > 0 {\n\t\tv, _ := pq.Pop()\n\t\tfmt.Printf("%d ", v)\n\t}\n\tfmt.Println()\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Извлечение min-heap: 3 10 27 42 85'}], 'under_the_hood': 'Куча хранится в непрерывном срезе: для узла `i` левый потомок `2i+1`, правый `2i+2`, родитель `(i-1)/2`.', 'pitfalls': 'Для максимальной кучи (Max-Heap) измените оператор сравнения на `>`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему PriorityQueue на куче эффективнее отсортированного слайса?»\n**Ответ:** Вставка в кучу стоит $O(\\log N)$, а в отсортированный срез — $O(N)$ из-за необходимости сдвигать элементы массива.'}, {'num': 97, 'title': 'Слияние двух мап: MergeMaps[K, V]', 'task': 'Создай дженерик-функцию `MergeMaps[K comparable, V any](m1, m2 map[K]V) map[K]V`, которая объединяет две мапы (при конфликте ключей выигрывает вторая мапа).', 'theory': 'Слияние двух мап создает новую хэш-таблицу с объединенными парами ключ-значение.', 'step_by_step': '1. Объявим `MergeMaps[K comparable, V any](m1, m2 map[K]V) map[K]V`.\n2. Создадим мапу `res := make(map[K]V, len(m1)+len(m2))`.\n3. Заполним из `m1`, затем из `m2`.\n4. В `main` объединим мапы.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport "fmt"\n\nfunc MergeMaps[K comparable, V any](m1, m2 map[K]V) map[K]V {\n\tres := make(map[K]V, len(m1)+len(m2))\n\tfor k, v := range m1 {\n\t\tres[k] = v\n\t}\n\tfor k, v := range m2 {\n\t\tres[k] = v\n\t}\n\treturn res\n}\n\nfunc main() {\n\tbase := map[string]int{"a": 1, "b": 2}\n\toverride := map[string]int{"b": 99, "c": 3}\n\n\tmerged := MergeMaps(base, override)\n\tfmt.Printf("Merged map: %+v\\n", merged)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Merged map: map[a:1 b:99 c:3]'}], 'under_the_hood': '`make(map[K]V, len(m1)+len(m2))` резервирует хэш-бакеты для исключения рехэширования.', 'pitfalls': 'Вторая мапа перезаписывает значения ключей первой мапы.', 'bigtech_interview': '**Вопрос с собеседования:** «Как работает maps.Copy в стандартной библиотеке Go 1.21+?»\n**Ответ:** `maps.Copy(dst, src)` копирует все пары из `src` в существующую мапу `dst` (in-place мутация без создания новой мапы).'}, {'num': 98, 'title': 'Пакетная обработка данных: BatchProcess[T, U]', 'task': 'Напишите функцию `BatchProcess[T any, U any](items []T, batchSize int, process func([]T) []U) []U`, которая разбивает слайс на чанки и обрабатывает их.', 'theory': 'Батчинг (Chunking / Batching) группирует элементы по `batchSize` для оптимизации пакетных запросов к СУБД (Bulk Insert).', 'step_by_step': '1. Объявим `BatchProcess[T any, U any](items []T, batchSize int, process func([]T) []U) []U`.\n2. В цикле с шагом `batchSize` выделим срез `items[i:end]`.\n3. Передадим чанк в `process` и саккумулируем результат.\n4. В `main` обработаем список ID пачками по 3 штуки.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport "fmt"\n\nfunc BatchProcess[T any, U any](items []T, batchSize int, process func([]T) []U) []U {\n\tif batchSize <= 0 {\n\t\tbatchSize = 100\n\t}\n\tvar result []U\n\tn := len(items)\n\n\tfor i := 0; i < n; i += batchSize {\n\t\tend := i + batchSize\n\t\tif end > n {\n\t\t\tend = n\n\t\t}\n\t\tchunk := items[i:end]\n\t\tres := process(chunk)\n\t\tresult = append(result, res...)\n\t}\n\treturn result\n}\n\nfunc main() {\n\tids := []int{101, 102, 103, 104, 105, 106, 107}\n\n\tprocessed := BatchProcess(ids, 3, func(chunk []int) []string {\n\t\tfmt.Printf("Обработка пачки %v (размер: %d)\\n", chunk, len(chunk))\n\t\tvar out []string\n\t\tfor _, id := range chunk {\n\t\t\tout = append(out, fmt.Sprintf("ID#%d_OK", id))\n\t\t}\n\t\treturn out\n\t})\n\n\tfmt.Println("Итог:", processed)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Обработка пачки [101 102 103] (размер: 3)\n# Обработка пачки [104 105 106] (размер: 3)\n# Обработка пачки [107] (размер: 1)\n# Итог: [ID#101_OK ID#102_OK ID#103_OK ID#104_OK ID#105_OK ID#106_OK ID#107_OK]'}], 'under_the_hood': 'Срезка `items[i:end]` использует тот же базовый массив без аллокаций памяти под сами элементы.', 'pitfalls': 'Проверяйте `end > len(items)` для предотвращения panic out of range.', 'bigtech_interview': '**Вопрос с собеседования:** «Зачем нужен батчинг при работе с базой данных?»\n**Ответ:** Батчинг сокращает сетевые Round-Trip Time (RTT) и накладные расходы транзакций: 1 запрос на 1000 строк работает в 50-100 раз быстрее, чем 1000 одиночных `INSERT`.'}, {'num': 99, 'title': 'Type Inference: автоматический вывод vs несовпадение типов', 'task': 'Покажи **type inference**: вызови `Max(3, 5)` без явного `[int]`. Покажи, когда inference работает. Затем попробуй `Max(3, int64(5))` — покажи, что inference **не может** выбрать общий тип (mismatched types).', 'theory': 'Нетипизированные числовые константы (`3, 5`) выводятся как `int`. При передаче разнотипных переменных `int` и `int64` Type Inference не может выбрать тип и требует явного приведения.', 'step_by_step': '1. Объявим `Max[T cmp.Ordered](a, b T) T`.\n2. Покажем успешный вызов с литералами `Max(3, 5)`.\n3. В комментариях покажем ошибку для `Max(3, int64(5))`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"cmp"\n\t"fmt"\n)\n\nfunc Max[T cmp.Ordered](a, b T) T {\n\tif a > b {\n\t\treturn a\n\t}\n\treturn b\n}\n\nfunc main() {\n\t// Нетипизированные константы успешно выводятся как int:\n\tfmt.Println("Max(3, 5) =", Max(3, 5))\n\n\t// Разные типы вызывают ошибку компилятора:\n\t// a := 3        // тип int\n\t// b := int64(5) // тип int64\n\t// fmt.Println(Max(a, b)) // ОШИБКА: mismatched types int and int64\n\n\t// Решение: явное приведение к общему типу:\n\tvar a int = 3\n\tvar b int64 = 5\n\tfmt.Println("Max с явным приведением:", Max(int64(a), b))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Max(3, 5) = 5\n# Max с явным приведением: 5'}], 'under_the_hood': 'Компилятор Go не использует концепцию «наименьшего общего типа» (Coercion), требуя строгого совпадения.', 'pitfalls': 'Всегда явно приводите типы числовых переменных перед вызовом generic-функций.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в Go литерал 3 может стать float64 или int, а переменная var x int = 3 не может?»\n**Ответ:** Литерал `3` — это нетипизированная константа (Untyped Constant) с произвольной точностью. Переменная `x` — это зафиксированный в памяти типизированный объект конкретного машинного формата.'}]
